#!/usr/bin/env bash
#
# PinPals — photographic headers across the app.
#
#   bash apply-app-backgrounds.sh
#
# Run it from the repo root (/workspaces/pinpals) on a branch off an
# up-to-date main. It writes 8 photographs, one new component, two helper
# scripts, and edits 10 screens. It changes nothing else, and it stops at the
# first thing that looks wrong rather than leaving you half-applied.
#
# Nothing here is a native dependency, so this ships over the air with
# `eas update` — no new TestFlight build.
set -euo pipefail

say()  { printf '\n\033[1m%s\033[0m\n' "$*"; }
die()  { printf '\n\033[31mSTOPPED: %s\033[0m\n' "$*" >&2; exit 1; }

# ---------------------------------------------------------------- checks ---
[ -f mobile/app.json ] && [ -d mobile/src/app ] \
  || die "run this from the repo root — the folder that has mobile/ in it"

[ -f mobile/src/lib/marketplace.ts ] \
  || die "the native marketplace is missing from this checkout. Pull main first: git pull origin main"

[ -e mobile/src/components/screen-header.tsx ] \
  && die "mobile/src/components/screen-header.tsx already exists — this has been applied already"

command -v base64 >/dev/null || die "base64 not found"
command -v sha256sum >/dev/null || die "sha256sum not found"

say "Unpacking…"
TMP=$(mktemp -d); trap 'rm -rf "$TMP"' EXIT

# The payload is a gzipped tar, base64'd. If a paste gets truncated or the
# editor eats a character, the checksum below fails and nothing is written —
# which is the whole reason it is here.
