PAYLOAD

EXPECTED=77fbd8165e3d5b027ff5e7f8bb6f361f638a0adf0c44679765c482684ad2cfc6
ACTUAL=$(sha256sum "$TMP/payload.tgz" | cut -d' ' -f1)
[ "$ACTUAL" = "$EXPECTED" ] || die "the payload did not survive the paste (checksum mismatch). Nothing was written — copy the script again."

tar -xzf "$TMP/payload.tgz" -C .

say "Checking what landed…"
for f in \
  mobile/assets/images/scenes/ballybunion.jpg \
  mobile/assets/images/scenes/coast-aerial.jpg \
  mobile/assets/images/scenes/dunes-gold.jpg \
  mobile/assets/images/scenes/lake-sunset.jpg \
  mobile/assets/images/scenes/links-dusk.jpg \
  mobile/assets/images/scenes/links-sunset.jpg \
  mobile/assets/images/scenes/old-head.jpg \
  mobile/assets/images/scenes/parkland.jpg \
  mobile/src/components/screen-header.tsx \
  mobile/tools/prep-scene-images.py \
  mobile/tools/check-scene-contrast.py
do
  [ -s "$f" ] || die "missing after unpack: $f"
done
printf '  %s files written\n' "$(git diff --name-only; git ls-files --others --exclude-standard)" >/dev/null
git status --short -- mobile/ | sed 's/^/  /'

say "Type-checking the app…"
( cd mobile && npx tsc --noEmit ) || die "tsc failed — tell Claude what it printed"

cat <<'DONE'

  Done. Everything type-checks.

  Have a look on your phone first if you like:
      cd mobile && npx expo start

  Then ship it:
      git checkout -b app-photo-headers
      git add -A mobile/
      git commit -F - <<'MSG'
Give the app screens photographic headers

Eight screens and the menu drawer get a photograph of an Irish or UK
course behind their title, from the images shared in the project.

The navy fade under each title is baked into the JPEG rather than laid
over it at runtime: a real gradient needs expo-linear-gradient, which is
a native module, which would mean a new TestFlight build instead of an
over-the-air update. It also means the contrast under the title is a
